import {vehiclePreviewMarkup} from './vehicle-volume.js';
import {VEHICLE_MODS,vehicleArt} from './vehicle-runtime.js';
export function vehiclePanel(g,data,{img,bar,display,esc,btn}){const s=g.s,v=g.vehicleStats(),art=vehicleArt(data.assets,s.vehicle);return `<div class="vehicle-profile"><span class="window-label">OUR RIDE</span>${vehiclePreviewMarkup(s.vehicle,v.name)}<h3>${v.name}</h3><p>${esc(display(g.driver()))} · 目前駕駛</p></div><div class="vehicle-stats"><div><small>車況</small><b>${s.vehicle.hp}<em> / ${s.vehicle.maxHp}</em></b>${bar(s.vehicle.hp,s.vehicle.maxHp,'hp')}</div><div><small>座位</small><b>${s.party.length}<em> / ${Math.min(4,v.seats)}</em></b></div><div><small>油箱</small><b>${s.resources.fuel}<em> / ${v.capacity}</em></b></div><div><small>裝甲減傷</small><b>${v.armor}</b></div></div><p class="vehicle-weapon"><small>車載武器</small><strong>${v.weapon.name}</strong><span>傷害加成 +${v.weapon.bonus}</span></p><p class="panel-explanation">公共背包備用汽油：${s.resources.fuelReserve||0}。停靠時自動補入油箱。</p><div class="section-label">車輛改裝<span>已用 ${v.used} / ${v.limit} 次 · 剩 ${Math.max(0,v.limit-v.used)} 次</span></div><div class="vehicle-mods">${s.vehicle.mods.map(k=>`<div><span>◇</span><strong>${VEHICLE_MODS[k]?.name||'舊式探照燈'}</strong></div>`).join('')||'<div class="empty-mod">尚未追加改裝；原車配備不占額度。</div>'}</div><p class="panel-explanation">修車廠可增加座位、裝甲、油箱或武器。每次消耗一份共用額度；換車後額度跟隨新車，舊改裝留在原車。</p>${s.offerVehicle?btn('查看發現的車輛','panel','offer','primary'):''}`;}
export function garagePanel(g,{btn}){const v=g.vehicleStats();return `${vehiclePreviewMarkup(g.s.vehicle,v.name)}<div class="garage-status"><strong>${v.name}</strong><span>改裝額度 ${v.used} / ${v.limit} · 剩 ${Math.max(0,v.limit-v.used)} 次</span><small>持有 ${g.s.resources.scrap} 廢料 · 維修不消耗改裝額度</small></div><div class="garage-options">${Object.keys(VEHICLE_MODS).map(id=>{const p=g.modificationPreview(id);return `<article class="garage-option"><h3>${p.name}</h3><p>${p.change}</p><small>${p.detail}</small>${btn(p.reason||'安裝 · '+p.price+' 廢料','buy','mod:'+id,'',!p.allowed)}</article>`;}).join('')}</div><div class="garage-repair"><p>車況 ${g.s.vehicle.hp} / ${g.s.vehicle.maxHp}</p>${btn('維修車輛 · 2 廢料','buy','repair:','',g.s.resources.scrap<2||g.s.vehicle.hp>=g.s.vehicle.maxHp)}</div>`;}
